    void writeBlocks() override {
        if (writer_ == nullptr)
            return;
        const std::uint32_t blockHandle = writer_->defineBlock(
            "LOCAL_BLOCK", DRW_Coord(0.0, 0.0, 0.0));
        if (blockHandle == 0 || !writer_->beginBlockContent(blockHandle))
            return;
        DRW_Line blockLine;
        blockLine.basePoint = DRW_Coord(80.0, 81.0, 0.0);
        blockLine.secPoint = DRW_Coord(82.0, 83.0, 0.0);
        wroteBlock_ = writer_->writeLine(&blockLine) && blockLine.handle != 0;
        DRW_Polyline blockPolyline;
        blockPolyline.vertexcount = 2;
        blockPolyline.addVertex(DRW_Vertex(86.0, 87.0, 0.0, 0.0));
        blockPolyline.addVertex(DRW_Vertex(88.0, 89.0, 0.0, 0.0));
        wroteBlockPolyline_ = writer_->writePolyline(&blockPolyline)
            && blockPolyline.handle != 0;
        if (wroteBlockPolyline_)
            recordWrittenPolyline(blockPolyline);
        if (expectedVersion_ >= DRW::AC1032 && writeOuterAnnotativeAttdef_) {
            DRW_Attdef annotativeAttdef;
            annotativeAttdef.tag = "LOCAL_ANNOTATIVE_ATTDEF";
            annotativeAttdef.prompt = "LOCAL_ANNOTATIVE_PROMPT";
            annotativeAttdef.text = "LOCAL_ATTDEF_VALUE";
            annotativeAttdef.basePoint = DRW_Coord(90.0, 91.0, 2.0);
            annotativeAttdef.height = 2.5;
            annotativeAttdef.attVersion = 1;
            annotativeAttdef.m_attributeType = 4;
            annotativeAttdef.attribFlags = 2;
            annotativeAttdef.lockPosition = true;
            annotativeAttdef.mtext = std::make_unique<DRW_MText>();
            annotativeAttdef.mtext->text = "LOCAL_ATTDEF_MTEXT";
            annotativeAttdef.mtext->basePoint = DRW_Coord(90.0, 91.0, 2.0);
            annotativeAttdef.m_r2018OuterAnnotativeData =
                {0xA5u, 0x5Au, 0xC3u, 0x3Cu};
            annotativeAttdef.m_r2018OuterAnnotativeAppHandle = 0xF00DCAFDu;
            annotativeAttdef.m_r2018OuterAnnotativeAppIdName =
                "LOCAL_ANNOTATIVE_APP";
            wroteOuterAnnotativeAttdef_ = writer_->writeAttdef(&annotativeAttdef)
                && annotativeAttdef.handle != 0;
            outerAnnotativeAttdefSourceHandlePreserved_ =
                annotativeAttdef.m_r2018OuterAnnotativeAppHandle == 0xF00DCAFDu;
        }
        if (expectedVersion_ >= DRW::AC1032) {
            DRW_Line lineAfterAnnotativeAttdef;
            lineAfterAnnotativeAttdef.basePoint = DRW_Coord(92.0, 93.0, 4.0);
            lineAfterAnnotativeAttdef.secPoint = DRW_Coord(94.0, 95.0, 6.0);
            wroteLineAfterOuterAnnotativeAttdef_ =
                writer_->writeLine(&lineAfterAnnotativeAttdef)
                && lineAfterAnnotativeAttdef.handle != 0;
        }
        wroteBlockContent_ = writer_->endBlockContent();
    }
