    void addAttDef(const DRW_Attdef& data) override {
        if (data.tag == "LOCAL_ANNOTATIVE_ATTDEF") {
            readOuterAnnotativeAttdefSeen_ = data.prompt
                    == "LOCAL_ANNOTATIVE_PROMPT"
                && data.text == "LOCAL_ATTDEF_VALUE"
                && data.attVersion == 1
                && data.m_attributeType == 4
                && data.mtext != nullptr
                && data.mtext->text == "LOCAL_ATTDEF_MTEXT"
                && data.m_r2018OuterAnnotativeData
                    == std::vector<std::uint8_t>{0xA5u, 0x5Au, 0xC3u, 0x3Cu}
                && data.m_r2018OuterAnnotativeUnknown == 0u
                && data.m_r2018OuterAnnotativeAppHandle
                    == expectedOuterAnnotativeAppIdHandle_
                && data.m_r2018OuterAnnotativeAppIdName
                    == "LOCAL_ANNOTATIVE_APP"
                && data.attribFlags == 2u
                && data.lockPosition
                && data.styleH.ref != 0u;
            if (!readOuterAnnotativeAttdefSeen_)
                std::cerr << "R2018 ATTDEF readback: prompt=" << data.prompt
                          << " text=" << data.text << " attVersion="
                          << static_cast<unsigned>(data.attVersion)
                          << " type="
                          << static_cast<unsigned>(data.m_attributeType)
                          << " dataSize="
                          << data.m_r2018OuterAnnotativeData.size()
                          << " appHandle=0x" << std::hex
                          << data.m_r2018OuterAnnotativeAppHandle << std::dec
                          << " appName="
                          << data.m_r2018OuterAnnotativeAppIdName
                          << " flags="
                          << static_cast<unsigned>(data.attribFlags)
                          << " lock=" << data.lockPosition
                          << " style=0x" << std::hex << data.styleH.ref
                          << std::dec << " mtext="
                          << (data.mtext ? data.mtext->text : "<null>")
                          << "\n";
        }
        dx_iface::addAttDef(data);
    }
    void addInsert(const DRW_Insert& data) override {
        readInsertSeen_ = true;
        const bool ordinaryAttributes = data.attlist.size()
                == (expectedVersion_ >= DRW::AC1032 ? 3u : 2u)
            && data.attlist.front() != nullptr
            && data.attlist.front()->tag == "LOCAL_TAG"
            && data.attlist.front()->text == "LOCAL_VALUE"
            && data.attlist[1] != nullptr
            && data.attlist[1]->tag == "LOCAL_HIDDEN_ZERO_HEIGHT"
            && data.attlist[1]->text == "LOCAL_ZERO_VALUE"
            && data.attlist[1]->height == 0.0
            && (data.attlist[1]->attribFlags & 1u) != 0;
        bool outerAnnotativeAttribute = expectedVersion_ < DRW::AC1032;
        if (expectedVersion_ >= DRW::AC1032 && data.attlist.size() == 3u
            && data.attlist[2] != nullptr) {
            const DRW_Attrib& attribute = *data.attlist[2];
            outerAnnotativeAttribute = attribute.tag == "LOCAL_ANNOTATIVE_ATTRIB"
                && attribute.text == "LOCAL_ATTRIB_VALUE"
                && attribute.attVersion == 1
                && attribute.m_attributeType == 2
                && attribute.mtext != nullptr
                && attribute.mtext->text == "LOCAL_ATTRIB_MTEXT"
                && attribute.m_r2018OuterAnnotativeData
                    == std::vector<std::uint8_t>{0x11u, 0x22u, 0x44u}
                && attribute.m_r2018OuterAnnotativeUnknown == 0u
                && attribute.m_r2018OuterAnnotativeAppHandle
                    == expectedOuterAnnotativeAppIdHandle_
                && attribute.m_r2018OuterAnnotativeAppIdName
                    == "LOCAL_ANNOTATIVE_APP"
                && attribute.attribFlags == 4u
                && attribute.lockPosition
                && attribute.styleH.ref != 0u;
            if (!outerAnnotativeAttribute)
                std::cerr << "R2018 ATTRIB readback: tag=" << attribute.tag
                          << " text=" << attribute.text << " attVersion="
                          << static_cast<unsigned>(attribute.attVersion)
                          << " type="
                          << static_cast<unsigned>(attribute.m_attributeType)
                          << " dataSize="
                          << attribute.m_r2018OuterAnnotativeData.size()
                          << " appHandle=0x" << std::hex
                          << attribute.m_r2018OuterAnnotativeAppHandle << std::dec
                          << " appName="
                          << attribute.m_r2018OuterAnnotativeAppIdName
                          << " flags="
                          << static_cast<unsigned>(attribute.attribFlags)
                          << " lock=" << attribute.lockPosition
                          << " style=0x" << std::hex << attribute.styleH.ref
                          << std::dec << " mtext="
                          << (attribute.mtext ? attribute.mtext->text : "<null>")
                          << "\n";
        }
        readAttribSeen_ = ordinaryAttributes && outerAnnotativeAttribute;
        dx_iface::addInsert(data);
    }

