    bool readPolylineHandleChainsMatchExpected() const {
        if (expectedPolylineHandleChains_.empty()
            || readPolylineHandleChains_.size()
                   != expectedPolylineHandleChains_.size()) {
            return false;
        }
        auto expected = expectedPolylineHandleChains_;
        auto observed = readPolylineHandleChains_;
        std::sort(expected.begin(), expected.end());
        std::sort(observed.begin(), observed.end());
        return observed == expected;
    }
    bool readPolylineFrameCoverageMatchesExpected() const {
        if (expectedPolylineHandleChains_.empty()
            || !readDwgFrameCoverageReportSeen_) {
            return false;
        }
        for (const auto& chain : expectedPolylineHandleChains_) {
            if (chain.size() < 3u)
                return false;
            for (const std::uint32_t handle : chain) {
                const DRW_DwgFramePublication* publication = nullptr;
                std::size_t publicationCount = 0u;
                for (const auto& candidate : readDwgFramePublications_) {
                    if (candidate.m_handle == handle) {
                        publication = &candidate;
                        ++publicationCount;
                    }
                }
                if (publicationCount != 1u || publication == nullptr
                    || !publication->m_hasSourceLocation
                    || !publication->m_isEntity
                    || publication->m_sourceOffsetSpace
                           == DRW_DwgFrameOffsetSpace::Unknown) {
                    return false;
                }

                const DRW_DwgFrameCoverageEntry* coverage = nullptr;
                std::size_t coverageCount = 0u;
                for (const auto& candidate :
                     readDwgFrameCoverageReport_.m_entries) {
                    if (candidate.m_handle == handle) {
                        coverage = &candidate;
                        ++coverageCount;
                    }
                }
                if (coverageCount != 1u || coverage == nullptr
                    || coverage->m_sourceOffset
                           != publication->m_sourceOffset
                    || coverage->m_sourceMapOrdinal
                           != publication->m_sourceMapOrdinal
                    || coverage->m_sourceOffsetSpace
                           != publication->m_sourceOffsetSpace
                    || coverage->m_disposition
                           != DRW_DwgFrameDisposition::Published
                    || coverage->m_publicationCount != 1u) {
                    return false;
                }
            }
        }
        return true;
    }
