bool runDxfAc1027BodyAcdsProfileRefusal(
    const std::filesystem::path& directory, bool binary) {
    const auto nonce = std::chrono::steady_clock::now()
        .time_since_epoch().count();
    const auto output = directory
        / ("ac1027-body-acds-profile-refusal-"
           + std::to_string(nonce) + (binary ? "-binary.dxf" : "-ascii.dxf"));
    const std::string sentinel = "preserve destination for unqualified BODY AcDs";
    {
        std::ofstream stream(output, std::ios::binary | std::ios::trunc);
        stream << sentinel;
        if (!stream)
            return false;
    }

    const std::vector<std::uint8_t> payload = makeLocalSabCarrierToken();
    dx_data source;
    DRW_ModelerGeometry* body = addLocalAcdsDataStorageModeler(
        source, 0xFC2Bu, payload, DRW::BODY, false);
    if (body == nullptr) {
        std::error_code ignored;
        std::filesystem::remove(output, ignored);
        return false;
    }
    dx_iface exporter;
    const bool exported = exporter.fileExport(
        output.string(), DRW::AC1027, binary, &source, false);
    std::ifstream saved(output, std::ios::binary);
    const std::string after(std::istreambuf_iterator<char>{saved},
                            std::istreambuf_iterator<char>{});
    const bool bodyUnchanged = body->eType == DRW::BODY
        && body->handle == 0xFC2Bu
        && body->m_dwgSourceVersion == DRW::AC1027
        && body->hasDataStorageRecord
        && body->hasDataStorageBinaryData()
        && body->dataStorageHandle == body->handle
        && body->dataStorageHandleKey == "FC2B"
        && body->dataStorageData == payload;
    saved.close();
    std::error_code ignored;
    std::filesystem::remove(output, ignored);
    return !exported && after == sentinel && bodyUnchanged;
}

bool runModelerPayloadStatusTests() {
    using Status = DRW_ModelerGeometry::PayloadStatus;

    DRW_ModelerGeometry unknown(DRW::E3DSOLID);
    if (unknown.modelerPayloadStatus() != Status::Unknown
        || std::string(unknown.modelerPayloadStatusName()) != "unknown")
        return false;

    DRW_ModelerGeometry empty(DRW::E3DSOLID);
    empty.m_isEmpty = true;
    if (empty.modelerPayloadStatus() != Status::ExplicitlyEmpty
        || std::string(empty.modelerPayloadStatusName()) != "explicitly-empty")
        return false;

    DRW_ModelerGeometry dxfPayload(DRW::E3DSOLID);
    dxfPayload.m_rawBytes = {'A', 'B', 'C', 'D'};
    dxfPayload.m_dxfPayloadChunks.emplace_back(310, 1, 2);
    if (dxfPayload.modelerPayloadStatus() != Status::CarrierBytesPresent)
        return false;

    DRW_ModelerGeometry outOfBoundsChunk(DRW::E3DSOLID);
    outOfBoundsChunk.m_rawBytes = {'A', 'B'};
    outOfBoundsChunk.m_dxfPayloadChunks.emplace_back(310, 1, 2);
    if (outOfBoundsChunk.modelerPayloadStatus() != Status::Unknown)
        return false;

    DRW_ModelerGeometry inlinePayload(DRW::E3DSOLID);
    inlinePayload.m_dwgAcisPayload = {'S', 'A', 'B'};
    if (inlinePayload.modelerPayloadStatus() != Status::CarrierBytesPresent)
        return false;

    DRW_ModelerGeometry linkedPayload(DRW::E3DSOLID);
    linkedPayload.hasDataStorageRecord = true;
    linkedPayload.dataStorageData = {'A', 'C', 'D', 'S'};
    if (linkedPayload.modelerPayloadStatus() != Status::CarrierBytesPresent)
        return false;

    DRW_ModelerGeometry missingPayload(DRW::E3DSOLID);
    missingPayload.m_hasModelerData = true;
    missingPayload.m_bodyBitSize = 24;
    missingPayload.m_objectSize = 3;
    missingPayload.m_rawBytes = {0x44, 0x57, 0x47};
    if (missingPayload.modelerPayloadStatus() != Status::ExpectedButUnavailable)
        return false;

    DRW_ModelerGeometry missingDataStorage(DRW::E3DSOLID);
    missingDataStorage.setHasDataStorageBinaryData(true);
    if (missingDataStorage.modelerPayloadStatus()
        != Status::ExpectedButUnavailable)
        return false;

    DRW_ModelerGeometry contradictory(DRW::E3DSOLID);
    contradictory.m_isEmpty = true;
    contradictory.m_dwgAcisPayload = {'S', 'A', 'B'};
    if (contradictory.modelerPayloadStatus() != Status::Contradictory
        || std::string(contradictory.modelerPayloadStatusName())
            != "contradictory")
        return false;
    return true;
}

bool runDxfModelerRejectsDwgFramePayload() {
    const std::filesystem::path output = std::filesystem::temp_directory_path()
        / "libdxfrw-modeler-dwg-frame.dxf";
    std::error_code ec;
    std::filesystem::remove(output, ec);
    const std::string sentinel = "preserve destination for unqualified modeler";
    const auto seedDestination = [&]() {
        std::ofstream stream(output, std::ios::binary | std::ios::trunc);
        stream << sentinel;
        return static_cast<bool>(stream);
    };
    const auto destinationIsPreserved = [&]() {
        std::ifstream saved(output, std::ios::binary);
        const std::string after(std::istreambuf_iterator<char>{saved},
                                std::istreambuf_iterator<char>{});
        return after == sentinel;
    };
    dx_data source;
    auto* modeler = new DRW_ModelerGeometry(DRW::E3DSOLID);
    modeler->handle = 0xFC02u;
    modeler->m_rawBytes = {'A', 'B', 'C'};
    modeler->m_bodyBitSize = 24;
    modeler->m_objectSize = 3;
    source.mBlock->ent.push_back(modeler);
    if (!seedDestination())
        return false;
    dx_iface exporter;
    const bool exportOk = exporter.fileExport(output.string(), DRW::AC1024,
                                               false, &source, false);
    const bool frameDestinationPreserved = destinationIsPreserved();
    std::filesystem::remove(output, ec);
    if (exportOk || !frameDestinationPreserved)
        return false;

    dx_data extractedSource;
    auto* extracted = new DRW_ModelerGeometry(DRW::E3DSOLID);
    extracted->handle = 0xFC03u;
    extracted->m_dwgAcisPayload = {
        'A', 'C', 'I', 'S', ' ', 'B', 'i', 'n', 'a', 'r', 'y', 'F', 'i', 'l', 'e'};
    extractedSource.mBlock->ent.push_back(extracted);
    if (!seedDestination())
        return false;
    dx_iface extractedExporter;
    const bool extractedExportOk = extractedExporter.fileExport(
        output.string(), DRW::AC1024, false, &extractedSource, false);
    const bool extractedDestinationPreserved = destinationIsPreserved();
    std::filesystem::remove(output, ec);
    if (extractedExportOk || !extractedDestinationPreserved)
        return false;

    dx_data missingPayloadSource;
    auto* missingPayload = new DRW_ModelerGeometry(DRW::E3DSOLID);
    missingPayload->handle = 0xFC04u;
    missingPayload->m_dwgSourceVersion = DRW::AC1027;
    missingPayload->m_modelerVersion = 2;
    missingPayload->m_hasModelerData = true;
    missingPayloadSource.mBlock->ent.push_back(missingPayload);
    if (!seedDestination())
        return false;
    dx_iface missingPayloadExporter;
    const bool missingPayloadExportOk = missingPayloadExporter.fileExport(
        output.string(), DRW::AC1027, false, &missingPayloadSource, false);
    const bool missingPayloadDestinationPreserved = destinationIsPreserved();
    std::filesystem::remove(output, ec);
    return !missingPayloadExportOk && missingPayloadDestinationPreserved;
}

bool runDxfSurfaceSatCarrierRoundTrip() {
    const std::filesystem::path output = std::filesystem::temp_directory_path()
        / "libdxfrw-surface-sat-carrier.dxf";
    std::error_code ec;
    std::filesystem::remove(output, ec);
    const std::vector<std::uint8_t> payload{
        'A', 'C', 'I', 'S', ' ', 'S', 'A', 'T'};
    dx_data source;
    auto* surface = new DRW_PlaneSurface();
    surface->handle = 0xFB10u;
    surface->rawAcisData = payload;
    source.mBlock->ent.push_back(surface);
    dx_iface exporter;
    if (!exporter.fileExport(output.string(), DRW::AC1024, false,
                             &source, false)) {
        std::filesystem::remove(output, ec);
        return false;
    }
    dx_data imported;
    dx_iface importer;
    if (!importer.fileImport(output.string(), &imported, false)) {
        std::filesystem::remove(output, ec);
        return false;
    }
    std::filesystem::remove(output, ec);
    for (const DRW_Entity* entity : imported.mBlock->ent) {
        if (entity == nullptr || entity->eType != DRW::PLANESURFACE)
            continue;
        const auto* decoded = static_cast<const DRW_PlaneSurface*>(entity);
        return decoded->rawAcisData == payload
            && !decoded->dxfPayloadChunks.empty()
            && std::all_of(decoded->dxfPayloadChunks.begin(),
                           decoded->dxfPayloadChunks.end(),
                           [](const DRW_ModelerPayloadChunk& chunk) {
                               return chunk.m_groupCode == 1 || chunk.m_groupCode == 3;
                           });
    }
    return false;
}

